#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "h3api.h"
#include "polyfill.h"
#include "polygon.h"

int main(int argc, char** argv) {
    if (argc < 3) { fprintf(stderr, "usage: count res lat,lng lat,lng ...\n"); return 1; }
    int res = atoi(argv[1]);
    int n = argc - 2;
    LatLng *verts = malloc(n * sizeof(LatLng));
    for (int i = 0; i < n; i++) {
        sscanf(argv[i+2], "%lf,%lf", &verts[i].lat, &verts[i].lng);
    }
    GeoPolygon poly;
    poly.numHoles = 0;
    poly.holes = NULL;
    poly.geoloop.numVerts = n;
    poly.geoloop.verts = verts;

    for (uint32_t flags = 0; flags < CONTAINMENT_INVALID; flags++) {
        int64_t sz;
        H3Error err = maxPolygonToCellsSizeExperimental(&poly, res, flags, &sz);
        // actual count
        int64_t actual = 0;
        if (!err && sz < 4000000) {
            H3Index *out = calloc(sz, sizeof(H3Index));
            H3Error e2 = polygonToCellsExperimental(&poly, res, flags, out);
            // count non-null
            for (int64_t i = 0; i < sz; i++) if (out[i]) actual++;
            free(out);
        }
        printf("flags=%u est=%lld actual=%lld\n", flags, (long long)sz, (long long)actual);
    }
    return 0;
}
EOF
